	@ParameterizedTest
	@MethodSource("focusSelections")
	void facetsApplyToOneBoundEndpointWithOrWithinAndAcrossFacets(List<List<Object>> selection, Set<String> focus)
			throws Exception {
		add("urn:a", "urn:p", iri("urn:b"));
		add("urn:d", "urn:p", iri("urn:a"));
		add("urn:a", "urn:color", iri("urn:red"));
		add("urn:b", "urn:color", iri("urn:blue"));
		add("urn:c", "urn:color", iri("urn:red"));
		connection.add(iri("urn:a"), RDF.TYPE, iri("urn:Person"));
		connection.add(iri("urn:b"), RDF.TYPE, iri("urn:Org"));
		connection.add(vf.createBNode("blank"), iri("urn:q"), vf.createLiteral("bonjour", "fr"));
		add("urn:t", "urn:q", vf.createLiteral("2", XSD.INTEGER));
		Set<String> expected = new HashSet<>();
		try (var statements = connection.getStatements(null, null, null)) {
			while (statements.hasNext()) {
				var statement = statements.next();
				if (focus.contains(statement.getSubject().stringValue())
						|| focus.contains(statement.getObject().stringValue())) {
					expected.add(statement.getSubject().stringValue() + " " + statement.getPredicate().stringValue()
							+ " " + statement.getObject().stringValue());
				}
			}
		}
		assertThat(edges(generated(Map.of("action", "facet", "selection", selection))))
				.containsExactlyInAnyOrderElementsOf(expected);
	}

