	@Test
	void exactMatchesAndValueLabelsStayInTheChosenGraph() throws Exception {
		List<String> sources = IntStream.range(0, 241).mapToObj(index -> "urn:source:" + index).toList();
		for (String source : sources) {
			connection.add(iri(source), iri("urn:rating"), iri("urn:shared"), iri("urn:g"));
		}
		connection.add(iri("urn:source:0"), iri("urn:rating"), iri("urn:outside"), iri("urn:other"));
		connection.add(iri("urn:shared"), RDFS.LABEL, vf.createLiteral("Shared"), iri("urn:g"));
		connection.add(iri("urn:shared"), RDFS.LABEL, vf.createLiteral("Felles", "nb"), iri("urn:g"));
		connection.add(iri("urn:shared"), RDFS.LABEL, vf.createLiteral("Aardvark outside", "nb"), iri("urn:other"));
		assertThat(rows(exact(sources, "urn:shared", "urn:g"))).hasSize(241);
		assertThat(rows(exact(sources, "urn:outside", "urn:g"))).isEmpty();
		assertThat(rows(exact(sources, "urn:outside", "all"))).hasSize(1);
		Set<String> labels = new HashSet<>();
		for (BindingSet row : rows(generated(Map.of("action", "value-labels", "values", List.of("urn:shared"), "scope",
				"urn:g")))) {
			labels.add(text(row, "label"));
		}
		assertThat(labels).containsExactlyInAnyOrder("Shared", "Felles");
	}

