	@Test
	void numericRangesCompareFiniteNumericLexicalValuesAcrossDatatypes() throws Exception {
		add("urn:string", "urn:rating", vf.createLiteral("2"));
		add("urn:decimal", "urn:rating", vf.createLiteral("2.5", XSD.DECIMAL));
		add("urn:exponent", "urn:rating", vf.createLiteral("3e0", XSD.DOUBLE));
		add("urn:space", "urn:rating", vf.createLiteral(" 2.25 "));
		add("urn:language", "urn:rating", vf.createLiteral("2", "en"));
		add("urn:custom", "urn:rating", vf.createLiteral("2", iri("urn:custom")));
		add("urn:signed", "urn:rating", vf.createLiteral("+2.0", XSD.STRING));
		add("urn:unicode", "urn:rating", vf.createLiteral("\u00a02.5\u2003"));
		add("urn:typed-invalid", "urn:rating", vf.createLiteral("2oops", XSD.INTEGER));
		add("urn:low", "urn:rating", vf.createLiteral("1"));
		for (String invalid : List.of("NaN", "INF", "0x2", "", "2oops", "1e999")) {
			add("urn:invalid:" + invalid.length(), "urn:rating", vf.createLiteral(invalid));
		}
		assertThat(edges(rangeQuery("number", "2", "3"))).containsExactlyInAnyOrder("urn:string urn:rating 2",
				"urn:decimal urn:rating 2.5", "urn:exponent urn:rating 3e0", "urn:space urn:rating  2.25 ",
				"urn:language urn:rating 2", "urn:custom urn:rating 2", "urn:signed urn:rating +2.0",
				"urn:unicode urn:rating \u00a02.5\u2003");
	}

