	@Test
	void openNumericRangesRejectOverflowAndInvalidNumericDatatypes() throws Exception {
		add("urn:valid", "urn:rating", vf.createLiteral("+2e0", XSD.STRING));
		add("urn:overflow", "urn:rating", vf.createLiteral("1e999", XSD.DOUBLE));
		add("urn:invalid", "urn:rating", vf.createLiteral("2oops", XSD.INTEGER));
		assertThat(edges(rangeQuery("number", "1", ""))).containsExactly("urn:valid urn:rating +2e0");
		assertThat(edges(rangeQuery("number", "0x2", "1e999"))).containsExactly("urn:valid urn:rating +2e0");
	}

	@Test
	void dateRangesRejectImpossibleCalendarDatesAndClockFields() throws Exception {
		add("urn:leap", "urn:rating", vf.createLiteral("2024-02-29Z", XSD.DATE));
		add("urn:invalid-day", "urn:rating", vf.createLiteral("2024-02-30", XSD.DATE));
		add("urn:invalid-time", "urn:rating", vf.createLiteral("2024-02-29T25:00:00", XSD.DATETIME));
		add("urn:invalid-zone", "urn:rating", vf.createLiteral("2024-02-29T12:00:00+15:00", XSD.DATETIME));
		assertThat(edges(rangeQuery("date", "2024-02-01", "2024-03-01")))
				.containsExactly("urn:leap urn:rating 2024-02-29Z");
	}

	private String rangeQuery(String kind, String from, String to) throws Exception {
		return generated(Map.of("action", "facet", "selection", List.of(List.of("urn:rating", List.of("__no_match__"))),
				"ranges", List.of(List.of("urn:rating", Map.of("kind", kind, "from", from, "to", to)))));
	}

	private void annotationData(Resource selected, Resource other) {
		Value triple = vf.createTripleTerm(iri("urn:a"), iri("urn:p"), iri("urn:b"));
		connection.add(iri("urn:claim"), RDF.REIFIES, triple, selected);
		connection.add(iri("urn:bare"), RDF.REIFIES, triple, selected);
		for (String id : List.of("urn:classic", "urn:empty")) {
			connection.add(iri(id), RDF.SUBJECT, iri("urn:a"), selected);
			connection.add(iri(id), RDF.PREDICATE, iri("urn:p"), selected);
			connection.add(iri(id), RDF.OBJECT, iri("urn:b"), selected);
		}
		for (String id : List.of("urn:claim", "urn:classic")) {
			connection.add(iri(id), iri("urn:confidence"), vf.createLiteral("selected"), selected);
			connection.add(iri(id), iri("urn:confidence"), vf.createLiteral("outside"), other);
		}
		connection.add(iri("urn:bare"), iri("urn:confidence"), vf.createLiteral("outside"), other);
		connection.add(iri("urn:empty"), iri("urn:confidence"), vf.createLiteral("outside"), other);
		connection.add(iri("urn:reference"), iri("urn:believes"), triple, selected);
		connection.add(iri("urn:outsideReference"), iri("urn:believes"), triple, other);
	}

	private List<String> annotations(String scope, boolean tripleTerms) throws Exception {
		return annotations(scope, tripleTerms, null);
	}

	private List<String> annotations(String scope, boolean tripleTerms, Dataset dataset) throws Exception {
		return rows(generated(Map.of("action", "annotations", "scope", scope, "tripleTerms", tripleTerms, "statement",
				Map.of("subject", "<urn:a>", "predicate", "<urn:p>", "object", "<urn:b>"))), dataset)
						.stream()
						.map(row -> text(row, "kind") + " " + text(row, "about") + " " + text(row, "property") + " "
								+ text(row, "value"))
						.toList();
	}

	private static String text(BindingSet row, String name) {
		return row.hasBinding(name) ? row.getValue(name).stringValue() : "-";
	}

	private Set<String> edges(String query) {
		Set<String> values = new HashSet<>();
		for (BindingSet row : rows(query)) {
			values.add(text(row, "source") + " " + text(row, "predicate") + " " + text(row, "target"));
		}
		return values;
	}

	private List<BindingSet> rows(String query) {
		return rows(query, null);
	}

	private List<BindingSet> rows(String query, Dataset dataset) {
		var prepared = connection.prepareTupleQuery(query);
		if (dataset != null) {
			prepared.setDataset(dataset);
		}
		try (var result = prepared.evaluate()) {
			return result.stream().toList();
		}
	}

	private void add(String subject, String predicate, Value object) {
		connection.add(iri(subject), iri(predicate), object);
	}

	private IRI iri(String value) {
		return vf.createIRI(value);
	}

	private static String generated(Map<String, ?> request) throws IOException, InterruptedException {
		String node = System.getProperty("os.name").startsWith("Windows") ? "node.exe" : "node";
		Path bundledNode = Path.of("target", "node", node);
		Path directory = Files.createDirectories(Path.of("target/generated-facet-queries"));
		Path output = Files.createTempFile(directory, "query-", ".rq");
		Path errors = Files.createTempFile(directory, "generator-", ".log");
		Path input = Files.createTempFile(directory, "request-", ".json");
		Files.writeString(input, JSON.writeValueAsString(request));
		Process process = new ProcessBuilder(Files.isExecutable(bundledNode) ? bundledNode.toString() : node,
				"--experimental-strip-types", "src/test/frontend/graph-explorer/fixtures/facet-regression-bridge.mjs",
				"--request-file", input.toString()).redirectOutput(output.toFile())
						.redirectError(errors.toFile())
						.start();
		if (!process.waitFor(30, TimeUnit.SECONDS)) {
			process.destroyForcibly();
			throw new AssertionError("Node query generator did not finish; see " + errors);
		}
		assertThat(process.exitValue()).as(Files.readString(errors)).isZero();
		return Files.readString(output);
	}
